const CACHE_TTL = 6 * 60 * 60 * 1000; // 6 hours - locations rarely change
const PAT = 'AIRTABLE_PAT_REDACTED';
const BASE_ID = 'appmBaUD39bNFM4QA';
const TABLE_ID = 'tbltUIpyKYxotKJN4';

const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = toolCall.function?.arguments || {};
if (typeof args === 'string') args = JSON.parse(args);

let cacheKey, formula;
if (args.city) {
  cacheKey = 'city_' + args.city.toLowerCase();
  formula = 'AND({Active}=TRUE(),SEARCH(LOWER("' + args.city + '"),LOWER({City})))';
} else if (args.state) {
  cacheKey = 'state_' + args.state.toUpperCase();
  formula = 'AND({Active}=TRUE(),{State}="' + args.state.toUpperCase() + '")';
} else if (args.name) {
  cacheKey = 'name_' + args.name.toLowerCase();
  formula = 'AND({Active}=TRUE(),SEARCH(LOWER("' + args.name + '"),LOWER({Location Name})))';
} else {
  cacheKey = 'all_active';
  formula = '{Active}=TRUE()';
}

const cache = $getWorkflowStaticData('global');
const now = Date.now();
const hit = cache[cacheKey];
let records;

if (hit && (now - hit.ts) < CACHE_TTL) {
  records = hit.data;
} else {
  const url = 'https://api.airtable.com/v0/' + BASE_ID + '/' + TABLE_ID +
    '?filterByFormula=' + encodeURIComponent(formula);
  const res = await this.helpers.httpRequest({ method: 'GET', url, headers: { Authorization: 'Bearer ' + PAT } });
  records = res.records || [];
  cache[cacheKey] = { data: records, ts: now };
}

if (records.length === 0) {
  return [{ json: { results: [{ toolCallId, result: 'No locations found for that area.' }] } }];
}

const lines = records.map(r => {
  const f = r.fields;
  let info = (f['Location Name'] || '') + ' - ' + (f['Address'] || '') + ', ' + (f['City'] || '') + ', ' + (f['State'] || '');
  if (f['Phone']) info += ' | ' + f['Phone'];
  if (f['Hours Mon-Sat']) info += ' | Mon-Sat: ' + f['Hours Mon-Sat'];
  if (f['Hours Sunday']) info += ' | Sun: ' + f['Hours Sunday'];
  return info;
});

return [{ json: { results: [{ toolCallId, result: lines.join('\n') }] } }];
